import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Breakpoints","description":"Pause and modify HTTP traffic in real time with NectoProxy breakpoints.","frontmatter":{"title":"Breakpoints","description":"Pause and modify HTTP traffic in real time with NectoProxy breakpoints."},"headers":[],"relativePath":"features/breakpoints.md","filePath":"features/breakpoints.md","lastUpdated":1772297611000}'),i={name:"features/breakpoints.md"};function o(r,e,p,l,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="breakpoints" tabindex="-1">Breakpoints <a class="header-anchor" href="#breakpoints" aria-label="Permalink to &quot;Breakpoints&quot;">​</a></h1><p>Breakpoints let you <strong>pause HTTP traffic mid-flight</strong> so you can inspect and modify requests or responses before they continue to their destination. Think of them as debugger breakpoints, but for network traffic instead of code execution.</p><p>When a breakpoint is triggered, the intercepted message is displayed in the NectoProxy UI where you can edit headers, body content, status codes, and more. Once you are satisfied with your changes, you resume the request and it continues on its way.</p><h2 id="breakpoint-types" tabindex="-1">Breakpoint Types <a class="header-anchor" href="#breakpoint-types" aria-label="Permalink to &quot;Breakpoint Types&quot;">​</a></h2><p>NectoProxy supports three breakpoint modes:</p><h3 id="request-breakpoints" tabindex="-1">Request Breakpoints <a class="header-anchor" href="#request-breakpoints" aria-label="Permalink to &quot;Request Breakpoints&quot;">​</a></h3><p>Pause <strong>outgoing requests</strong> before they are sent to the server. When triggered, you can inspect and modify:</p><ul><li>Request URL and path</li><li>HTTP method</li><li>Request headers</li><li>Request body</li></ul><p>This is useful when you want to alter what the server receives without modifying your application code.</p><h3 id="response-breakpoints" tabindex="-1">Response Breakpoints <a class="header-anchor" href="#response-breakpoints" aria-label="Permalink to &quot;Response Breakpoints&quot;">​</a></h3><p>Pause <strong>incoming responses</strong> before they are delivered to the client. When triggered, you can inspect and modify:</p><ul><li>HTTP status code and reason phrase</li><li>Response headers</li><li>Response body</li></ul><p>This is useful when you want to test how your application handles specific server responses.</p><h3 id="both-request-response" tabindex="-1">Both (Request + Response) <a class="header-anchor" href="#both-request-response" aria-label="Permalink to &quot;Both (Request + Response)&quot;">​</a></h3><p>Pause the traffic <strong>twice</strong> -- once when the request is about to be sent to the server, and again when the response comes back. This gives you full control over both directions of the communication.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use &quot;Both&quot; mode sparingly, as it requires two manual interactions per request. In most debugging scenarios, pausing only the request or only the response is sufficient.</p></div><h2 id="breakpoint-conditions" tabindex="-1">Breakpoint Conditions <a class="header-anchor" href="#breakpoint-conditions" aria-label="Permalink to &quot;Breakpoint Conditions&quot;">​</a></h2><p>Breakpoints can be configured with conditions that determine which traffic triggers the pause. Without conditions, a breakpoint will pause <strong>all</strong> traffic, which is rarely what you want.</p><h3 id="url-pattern" tabindex="-1">URL Pattern <a class="header-anchor" href="#url-pattern" aria-label="Permalink to &quot;URL Pattern&quot;">​</a></h3><p>Match requests by their URL using the same pattern syntax as the <a href="./rules-engine.html">Rules Engine</a>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.example.com/v1/users/*</span></span>
<span class="line"><span>*api/checkout*</span></span>
<span class="line"><span>regex:.*\\\\.example\\\\.com/api/v[23]/.*</span></span></code></pre></div><h3 id="method-filter" tabindex="-1">Method Filter <a class="header-anchor" href="#method-filter" aria-label="Permalink to &quot;Method Filter&quot;">​</a></h3><p>Restrict the breakpoint to specific HTTP methods:</p><ul><li><code>GET</code> -- Only pause GET requests</li><li><code>POST</code> -- Only pause POST requests</li><li><code>PUT</code>, <code>DELETE</code>, <code>PATCH</code>, <code>HEAD</code>, <code>OPTIONS</code></li></ul><p>You can select multiple methods. If no method is specified, the breakpoint matches all methods.</p><h3 id="header-conditions" tabindex="-1">Header Conditions <a class="header-anchor" href="#header-conditions" aria-label="Permalink to &quot;Header Conditions&quot;">​</a></h3><p>Trigger breakpoints based on request header values:</p><table tabindex="0"><thead><tr><th>Header</th><th>Condition</th><th>Value</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>equals</td><td><code>application/json</code></td></tr><tr><td><code>Authorization</code></td><td>contains</td><td><code>Bearer</code></td></tr><tr><td><code>X-Debug</code></td><td>exists</td><td>--</td></tr></tbody></table><h2 id="condition-logic" tabindex="-1">Condition Logic <a class="header-anchor" href="#condition-logic" aria-label="Permalink to &quot;Condition Logic&quot;">​</a></h2><p>When multiple conditions are configured on a single breakpoint, you can choose how they are combined:</p><h3 id="and-logic-all-conditions-must-match" tabindex="-1">AND Logic (All conditions must match) <a class="header-anchor" href="#and-logic-all-conditions-must-match" aria-label="Permalink to &quot;AND Logic (All conditions must match)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL contains:     /api/users</span></span>
<span class="line"><span>Method equals:    POST</span></span>
<span class="line"><span>Header exists:    Authorization</span></span></code></pre></div><p>With AND logic, the breakpoint only triggers when the request matches <strong>all three</strong> conditions -- it must be a POST request to a URL containing <code>/api/users</code> that includes an Authorization header.</p><h3 id="or-logic-any-condition-can-match" tabindex="-1">OR Logic (Any condition can match) <a class="header-anchor" href="#or-logic-any-condition-can-match" aria-label="Permalink to &quot;OR Logic (Any condition can match)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL contains:     /api/checkout</span></span>
<span class="line"><span>URL contains:     /api/payment</span></span></code></pre></div><p>With OR logic, the breakpoint triggers when <strong>any one</strong> of the conditions matches -- it pauses requests to either the checkout or payment endpoint.</p><details class="details custom-block"><summary>Combining AND and OR</summary><p>For more complex scenarios, you can create multiple breakpoints with different condition logic. For example, create one breakpoint with AND conditions for a specific scenario and another with OR conditions for a broader catch. Breakpoints are evaluated independently.</p></details><h2 id="what-happens-when-a-breakpoint-triggers" tabindex="-1">What Happens When a Breakpoint Triggers <a class="header-anchor" href="#what-happens-when-a-breakpoint-triggers" aria-label="Permalink to &quot;What Happens When a Breakpoint Triggers&quot;">​</a></h2><p>When a matching request or response hits a breakpoint, the following occurs:</p><ol><li><strong>Traffic is paused</strong> -- The request or response is held in memory and does not proceed.</li><li><strong>UI notification</strong> -- NectoProxy displays a prominent notification indicating that traffic has been intercepted.</li><li><strong>Intercept panel opens</strong> -- The intercepted message is shown in an editable panel with the full request or response details.</li><li><strong>You make changes</strong> -- Edit any part of the intercepted message (headers, body, URL, status code, etc.).</li><li><strong>You take action</strong> -- Either resume or drop the intercepted message.</li></ol><h3 id="editing-intercepted-traffic" tabindex="-1">Editing Intercepted Traffic <a class="header-anchor" href="#editing-intercepted-traffic" aria-label="Permalink to &quot;Editing Intercepted Traffic&quot;">​</a></h3><p>The intercept panel provides a full editor for the paused message:</p><p><strong>For intercepted requests:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Method:  [POST          v]</span></span>
<span class="line"><span>URL:     [https://api.example.com/v1/users]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Headers:</span></span>
<span class="line"><span>  Content-Type:   application/json</span></span>
<span class="line"><span>  Authorization:  Bearer eyJhbGciOi...</span></span>
<span class="line"><span>  X-Custom:       my-value</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Body:</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;Jane Doe&quot;,</span></span>
<span class="line"><span>  &quot;email&quot;: &quot;jane@example.com&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>For intercepted responses:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Status:  [200] [OK]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Headers:</span></span>
<span class="line"><span>  Content-Type:     application/json</span></span>
<span class="line"><span>  Cache-Control:    no-cache</span></span>
<span class="line"><span>  X-Request-Id:     abc-123</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Body:</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;id&quot;: 456,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;Jane Doe&quot;,</span></span>
<span class="line"><span>  &quot;created&quot;: true</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>You can freely edit any field. The modified version is what gets forwarded to its destination.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p>When traffic is paused at a breakpoint, you have two choices:</p><h3 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h3><p>Forward the (potentially modified) message to its destination. The request continues to the server, or the response continues to the client, with whatever changes you have made.</p><h3 id="drop" tabindex="-1">Drop <a class="header-anchor" href="#drop" aria-label="Permalink to &quot;Drop&quot;">​</a></h3><p>Discard the intercepted message entirely. For a paused request, the client receives a connection error. For a paused response, the client receives no response (effectively a timeout from the client&#39;s perspective).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Dropping a request or response will cause the client to experience an error. Use this action intentionally -- for example, to test how your application handles network failures.</p></div><h2 id="timeout-and-auto-continue" tabindex="-1">Timeout and Auto-Continue <a class="header-anchor" href="#timeout-and-auto-continue" aria-label="Permalink to &quot;Timeout and Auto-Continue&quot;">​</a></h2><p>To prevent breakpoints from blocking traffic indefinitely (for example, if you step away from your desk or forget about a paused request), NectoProxy includes a configurable <strong>auto-continue timeout</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Timeout duration</strong></td><td>30 seconds</td><td>How long a breakpoint waits before auto-resuming</td></tr><tr><td><strong>Auto-continue action</strong></td><td>Resume</td><td>What happens when the timeout expires (Resume or Drop)</td></tr></tbody></table><p>When the timeout expires, the intercepted message is automatically resumed (or dropped, depending on your configuration) without modification.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can adjust the timeout duration in the breakpoint settings. Set it to a longer value (e.g., 120 seconds) if you need more time to inspect and modify traffic, or disable auto-continue entirely if you always want manual control.</p></div><h2 id="practical-use-cases" tabindex="-1">Practical Use Cases <a class="header-anchor" href="#practical-use-cases" aria-label="Permalink to &quot;Practical Use Cases&quot;">​</a></h2><h3 id="testing-authentication-flows" tabindex="-1">Testing Authentication Flows <a class="header-anchor" href="#testing-authentication-flows" aria-label="Permalink to &quot;Testing Authentication Flows&quot;">​</a></h3><p>Pause a login request and modify the credentials to test how the server handles different inputs:</p><ol><li>Create a breakpoint on <code>POST /api/auth/login</code></li><li>Submit the login form in your application</li><li>When the breakpoint triggers, modify the request body:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wrong-password&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li>Resume the request and observe the server&#39;s error response</li><li>Verify your UI displays the appropriate error message</li></ol><h3 id="modifying-api-response-payloads" tabindex="-1">Modifying API Response Payloads <a class="header-anchor" href="#modifying-api-response-payloads" aria-label="Permalink to &quot;Modifying API Response Payloads&quot;">​</a></h3><p>Test how your UI handles edge cases in API responses:</p><ol><li>Create a response breakpoint on <code>GET /api/products</code></li><li>Trigger the API call from your application</li><li>When the response breakpoint triggers, modify the body to include edge-case data:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;products&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;No products found&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li>Resume the response and verify your UI renders the empty state correctly</li></ol><h3 id="debugging-race-conditions" tabindex="-1">Debugging Race Conditions <a class="header-anchor" href="#debugging-race-conditions" aria-label="Permalink to &quot;Debugging Race Conditions&quot;">​</a></h3><p>Use breakpoints to control the timing of concurrent requests:</p><ol><li>Create request breakpoints on two API endpoints that your application calls concurrently</li><li>Trigger the concurrent calls from your application</li><li>Both requests are paused at their breakpoints</li><li>Resume them in a specific order to test how your application handles different response orderings</li><li>This technique is invaluable for reproducing and fixing race condition bugs</li></ol><h3 id="simulating-server-errors" tabindex="-1">Simulating Server Errors <a class="header-anchor" href="#simulating-server-errors" aria-label="Permalink to &quot;Simulating Server Errors&quot;">​</a></h3><p>Test error handling by modifying response status codes:</p><ol><li>Create a response breakpoint on your API endpoint</li><li>When the response arrives, change the status code to <code>500</code> and set the body to:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Internal Server Error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Database connection timeout&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li>Resume the modified response to see how your application handles the error</li></ol><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Breakpoints are session-level settings. They are active only while NectoProxy is running and must be reconfigured if you restart the proxy. For persistent traffic modifications, use the <a href="./rules-engine.html">Rules Engine</a> instead.</p></div>`,74)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
